        return -1  # No tree can fulfill the conditions
    else:
        # For balanced alternating trees
        if black_count == white_count:
            return black_count
        else:
            # For the remaining, not equal up to half count, make a change so that the
            # diameter will have alternate colors
            if black_count > white_count:
                nodes = ['W'] * white_count + ['B'] * (black_count - white_count)
            else:
                nodes = ['B'] * black_count + ['W'] * (white_count - black_count)
            if nodes.count('W') >= 1:
