@lru_cache(maxsize=None)
def lcm(a, b):
    return (a * b) // gcd(a, b)

def ext_gcd(a, b):
    if b == 0:
        return (a, 1, 0)
    else:
        (_, x1, y1) = ext_gcd(b, a % b)
        return (x1, y1 - (a // b) * x1, x1)

def inverse(a):
    x, _, _ = ext_gcd(a, MOD)
    return x % MOD

@lru_cache(maxsize=None)
def binomial_coefficient(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    return binomial_coefficient(n-1, k-1) + binomial_coefficient(n-1, k)

@lru_cache(maxsize=None)
def permutations(n, k):
    if k == 0 or n == k:
        return 1
    return permutations(n-1, k-1) * (k - (n - k))

