import itertools

def calculate_ratings(order):
    A_and_B = sum('A' in e for e in order)
    first_player_sum = 0
    second_player_sum = 0

    for i, e in enumerate(order):
        if e == 'A':
            first_player_sum += (A_and_B - A_and_B % 2) - (i % 2)
            second_player_sum += (A_and_B - (A_and_B-1) % 2) - (i % 2)
        else:
            first_player_sum += A_and_B - 1 - i % 2
            second_player_sum -= A_and_B - 1 - i % 2

    unfairness = abs(first_player_sum - second_player_sum)
    return unfairness

