from math import comb

def is_valid(order):
    unfairness = ord('B') - ord('A')
    player1_earnings_before = unfairness * sum(order.count(c) for c in 'AABBB')
    player2_earnings_before = sum(order.count(c) for c in 'AABAAB')

    for i in range(1, len(order)):
        if order[i-1] != '?':
            player1_earnings_before += unfairness - ord(order[i-1]) + ord(order[i])
        else:
            player1_earnings_before += unfairness - ord(order[i])

    if order[0] != '?':
        player2_earnings_before += unfairness - ord(order[0]) + ord(order[1])
    else:
        player2_earnings_before += unfairness - ord(order[0])

    return max(player1_earnings_before, player2_earnings_before) > (R + C) // 2

def get_valid_orderings_for(S):
    R, C = len(S) // 2, len(S) // 2
    possible_orderings = []

    def backtrack(position):
        if position >= len(S):
            for k in range(len(ordering)):
                invalid = False
                for i in range(k, k + R):  # Since packs of raw & cooked eggs are equal length, positions start at front and same length as players order validity check
                    if ordering[i % k] != '?' and ordering[i % k] != 'B':
                        invalid = True
                        break
                    elif ordering[i % k] == 'A' and i % k < R:
                        invalid = True
                        break
                    elif ordering[i % k] == 'B' and i % k >= R:
                        invalid = True
                        break
                if not invalid:
                    if k * R < R + 2 * C:
                        if not is_valid(ordering + ['B'] + ordering[0:k] + ['A'] + ordering[k + 1:]):
                            while ordering[-1] != '?' and ordering[-1] != 'B':
                                ordering.pop()
                            continue
                    invalid = False
            if invalid:
                return
            if len(S) < len(ordering):
                possible_orderings.append(ordering[:len(S)])
        else:
            current = 'A' if S[position] == '?' else S[position]
            ordering[position // R] = current
            backtrack(position + 1)
            ordering.pop()

    for ordering in backtrack(0):
        guaranteed_match = is_valid(ordering)
        if guaranteed_match:
            possible_orderings.append(ordering)
    return possible_orderings

