from itertools import permutations

def find_min_unfairness(order):
    unfairness = 0
    A_count = [0, 0]
    B_count = [0, 0]

    for i, symbol in enumerate(order[::2], start=1):
        if symbol == 'A':
            A_count[0] += 1
        else:
            B_count[0] += 1
        if symbol == 'B':
            B_count[1] += 1
        else:
            A_count[1] += 1

    B_diff = B_count[1] // 2
    A_diff = A_count[0] - B_count[0]

    unfairness = abs(A_count[1] - B_count[1] + A_count[0] - B_diff)

    return unfairness

def count_matching_orderings(S):
