    for order in permutations('AB', R):
        matched = True
        for i in range(len(S)):
            if S[i] != '?' and order[i] != S[i]:
                matched = False
                break
        if matched:
            valid_order = ''.join(order)
            invalid_order = valid_order.replace('A', 'B')
            invalid_order = invalid_order.replace('B', 'A')
            results.add(find_min_unfairness(invalid_order))

