def count_special_arrays(n, a):
    mod = 998244353
    dp = [0] * (n + 1)
    count = 0

    for val in a:
        if val == 1:
            return count % mod
        elif val == 2:
            count += dp[val] + dp[val] * val // 2
            if val % 2 != 0:    
                count += dp[val + 1] * (val - 2) // 2
                if val % 3 == 0:
                    count += dp[val + 2] * (val - 3) // 2
                    if val % 5 == 0:
                        count += dp[val + 3] * (val - 5) // 2
        else:
            count += dp[val] * (val - 1)

        dp[val + 1] =  (int)(dp[val])

    return count % mod

