from collections import defaultdict

def profit_interval_length(n, incomes, avg):
    inc_income_count = defaultdict(int)
    longest = 0
    current_total = 0

    for i in range(n):
        current_total += incomes[i]

        if incomes[i] != avg:
            inc_income_count[current_total] += 1
        else:
            longest = max(longest, len(inc_income_count))

    if n - longest < 2:
        return 0

    else:
        x, y = n - longest, n
        while x < y:
            mid = (x + y + 1) // 2
            count = defaultdict(int)
            current_total = 0
            current_count = 0
            for i in range(y - 1, n):
                current_total += incomes[i]
                count[current_total] += 1
                if current_total == 0:
                    current_count += 1
                if x <= current_count <= n - mid:
                    if mid * n - sum(count, 0) > x:
                        longest = max(longest, current_count)
                        x = mid
                    else:
                        y = mid - 1
    return longest

