import heapq

class SplitMonster:
    def __init__(self, id, li):
        self.id = id
        self.li = li

    def get_range(self):
        min_diamonds = -2
        max_diamonds = -2
        heap = []
        for i in range(self.li):
            if self.id == i + 1:
                heap.append(-i)
                break
            heap.append(-i)
        heapq.heapify(heap)
        current_diamonds = 0
        while heap:
            next_diamonds = (-heapq.heappop(heap) * 3)
            min_diamonds = min(min_diamonds, next_diamonds)
            max_diamonds = max(max_diamonds, next_diamonds)
            if current_diamonds * 3 < next_diamonds:
                break
            if current_diamonds + 1 < next_diamonds:
                min_diamonds = next_diamonds
                max_diamonds = -2
            delta = next_diamonds - (current_diamonds * 3)
            for j in range(delta + 1):
                heapq.heappush(heap, -((current_diamonds + j) * 3 + j))
            current_diamonds += 1
        return min_diamonds, max_diamonds

