import heapq
from math import inf

def find_minimum_collision_time(num_cars, cars):
    distances = [inf] * num_cars
    distances[0] = 0
    pq = [(0, 0)]
    collision_times = {}

    while pq:
        current_time, car_i = heapq.heappop(pq)
        if current_time in collision_times:
            continue
        collision_times[current_time] = inf

        for car_j, time in collision_times.items():
            if time < current_time:
                other_car_j_position, other_car_j_vector, other_car_j_speed, _ = cars[car_j]
                distance = other_car_j_position + other_car_j_vector * (current_time - time)
                if distance >= 1:
                    collision_time = max(current_time, time) + (distance - 1) // other_car_j_speed
                    if collision_time < distances[car_j]:
                        distances[car_j] = collision_time
                        heapq.heappush(pq, (collision_time, car_j))

    for i in range(num_cars):
        if distances[i] == inf:
            return "No show :("
    return min(distances)

