from itertools import permutations, product

def is_valid(ordering):
    counter = [0, 0]
    for i, player in enumerate(ordering):
        if player == 'A':
            counter[0] += 1
        else:
            counter[1] += 1
    return counter[0] == counter[1]

def count_matching(ordering, mask):
    winner_count = 0
    fair_count = 0

    for r in range(mask) + reversed(range(mask)):
        if bool(r & mask):
            winner_count += ordering[2::2].count('A')
            fair_count += ordering[2::2].count('B')

        if r in mask:
            winner_count += ordering[0].count('A')
            fair_count += ordering[0].count('B')

    return winner_count - fair_count

def main():
    R, C = map(int, input().split())
    S = input()

    valid_ordering_count = 0
    for i in range(1, R + 2):
